using Microsoft.EntityFrameworkCore;
class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();

    protected override void ConfigureConventions(ModelConfigurationBuilder configurationBuilder)
    {
        // EF Core 9 changed the discriminator property from "Discriminator" to "$type".
        // Revert to the EF8 name so existing documents and raw SQL queries keep working.
        configurationBuilder.Conventions.Remove(
            typeof(Microsoft.EntityFrameworkCore.Metadata.Conventions.CosmosDiscriminatorConvention));
    }

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");

            // EF Core 9 changed the discriminator property from "$type" convention;
            // restore the EF8 "Discriminator" property with the old value.
            entity.HasDiscriminator<string>("Discriminator")
                  .HasValue<Product>("Product");

            // EF Core 9 stores id as the raw key value ("123").
            // Existing documents use the EF8 format "Product|123".
            // Preserve the old format so reads against 500K documents keep working.
            entity.HasPartitionKey(p => p.Id);
            entity.Property(p => p.Id)
                  .ToJsonProperty("id")
                  .HasValueGenerator<EF8IdValueGenerator>();
        });
    }
}

/// <summary>
/// Reproduces the EF8 "EntityType|Key" id format so EF Core 9 can read
/// existing Cosmos documents written by EF Core 8.
/// </summary>
class EF8IdValueGenerator : Microsoft.EntityFrameworkCore.ValueGeneration.ValueGenerator<string>
{
    public override bool GeneratesTemporaryValues => false;
    public override string Next(Microsoft.EntityFrameworkCore.ChangeTracking.EntityEntry entry)
        => $"Product|{entry.Property("Id").CurrentValue}";
}

class Product { public int Id { get; set; } public string Sku { get; set; } }

